# ---------- Google Sheets adapter ----------
@st.cache_resource
@st.cache_resource(show_spinner=False)
def get_book():
    """Buka spreadsheet utama memakai Service Account dari Streamlit Secrets.

    Catatan: kepemilikan spreadsheet oleh akun Gmail pribadi tidak otomatis
    memberi akses kepada aplikasi. Google Sheets harus dibagikan ke
    `client_email` service account yang ada di st.secrets.
    """
    try:
        import gspread
        from google.oauth2.service_account import Credentials
        if "gcp_service_account" not in st.secrets:
            return None
        info = dict(st.secrets["gcp_service_account"])
        required = ["type", "project_id", "private_key", "client_email", "token_uri"]
        if any(not str(info.get(k, "")).strip() for k in required):
            return None
        creds = Credentials.from_service_account_info(
            info,
            scopes=[
                "https://www.googleapis.com/auth/spreadsheets",
                "https://www.googleapis.com/auth/drive",
            ],
        )
        return gspread.authorize(creds).open_by_key(SHEET_ID)
    except Exception:
        return None

def sheets_status():
    """Status ringkas koneksi untuk membantu deployment."""
    try:
        book = get_book()
        if book is not None:
            return True, f"Terhubung ke Google Sheets: {book.title}"
        # Coba baca sheet login lewat endpoint CSV jika spreadsheet memang publik.
        df = ws_df(LOGIN_SHEET, _status_probe=True)
        if not df.empty:
            return True, "Sheet login dapat dibaca melalui akses publik (read-only)."
        return False, "Google Sheets belum dapat diakses oleh aplikasi. Pastikan Secrets benar dan spreadsheet dibagikan ke client_email service account sebagai Editor."
    except Exception as e:
        return False, f"Koneksi Google Sheets gagal: {e}"

def ws_df(name, _status_probe=False):
    book=get_book()
    if book:
        try:
            ws=book.worksheet(name)
            values=ws.get_all_values()
            if not values:
                return pd.DataFrame()
            # Buang header kosong agar mapping kolom login lebih stabil.
            headers=[str(h).strip() for h in values[0]]
            return pd.DataFrame(values[1:], columns=headers)
        except Exception:
            pass
    # Fallback baca-only. Ini hanya berhasil jika spreadsheet/sheet dapat diakses publik.
    try:
        import urllib.parse
        url=f"https://docs.google.com/spreadsheets/d/{SHEET_ID}/gviz/tq?tqx=out:csv&sheet={urllib.parse.quote(name)}"
        return pd.read_csv(url, dtype=str).fillna("")
    except Exception:
        return pd.DataFrame()

def append_row(name, record):
    book=get_book()
    if not book:
        st.error("Google Sheets belum terhubung untuk mode tulis. Tambahkan service account pada Streamlit Secrets.")
        return False
    try:
        try: ws=book.worksheet(name)
        except Exception:
            ws=book.add_worksheet(title=name, rows=1000, cols=max(20,len(record)))
            ws.append_row(list(record.keys()))
        headers=ws.row_values(1)
        if not headers:
            headers=list(record.keys()); ws.append_row(headers)
        # Add newly introduced columns safely.
        missing=[k for k in record if k not in headers]
        if missing:
            headers += missing
            ws.update(values=[headers], range_name='A1')
        ws.append_row([str(record.get(h,"")) for h in headers], value_input_option="USER_ENTERED")
        st.cache_data.clear()
        return True
    except Exception as e:
        st.error(f"Gagal menulis ke Google Sheets: {e}")
        return False

def update_request(req_id, updates):
    book=get_book()
    if not book: return False
    try:
        ws=book.worksheet(REQUEST_SHEET); vals=ws.get_all_values()
        if not vals: return False
        headers=vals[0]
        id_col=next((i for i,h in enumerate(headers) if norm(h) in ['id request','no request','nomor request','request id']),0)
        row_idx=next((r for r,row in enumerate(vals[1:],start=2) if len(row)>id_col and row[id_col]==req_id),None)
        if not row_idx: return False
        for k,v in updates.items():
            if k not in headers:
                headers.append(k); ws.update_cell(1,len(headers),k)
            c=headers.index(k)+1; ws.update_cell(row_idx,c,str(v))
        st.cache_data.clear(); return True
    except Exception as e:
        st.error(f"Gagal memperbarui permohonan: {e}"); return False

def norm(x): return re.sub(r'\s+',' ',str(x).strip().lower())
def find_col(df, candidates):
    lookup={norm(c):c for c in df.columns}
    for c in candidates:
        if norm(c) in lookup: return lookup[norm(c)]
    return None

def getv(row, candidates, default="-"):
    for c in candidates:
        if c in row and str(row[c]).strip() not in ('','nan','None'): return str(row[c])
    return default

